import json
import numpy as np
import os

BASE_DIR = "/root/autodl-tmp/distrib_canary_collapse/results/alpha_sweep"
METRICS = ["token_entropy", "ece", "distinct_1", "distinct_2", "distinct_3", "mauve"]

def load_metrics(exp_dir):
    path = os.path.join(BASE_DIR, exp_dir, "all_metrics.json")
    if not os.path.exists(path):
        return None
    with open(path) as f:
        return json.load(f)

# Load baseline (a000_s42_fp32)
baseline = load_metrics("a000_s42_fp32")
baseline_gen0 = {m: baseline[0][m] for m in METRICS}

# Compute null experiment absolute deviations from gen0
null_deviations = {m: [] for m in METRICS}
for gen_data in baseline[1:]:
    for m in METRICS:
        null_deviations[m].append(abs(gen_data[m] - baseline_gen0[m]))

null_sigma = {m: float(np.std(null_deviations[m])) for m in METRICS}
threshold_2sigma = {m: 2 * null_sigma[m] for m in METRICS}

# Also compute relative thresholds (% of gen0 value) for interpretability
rel_threshold = {}
for m in METRICS:
    if abs(baseline_gen0[m]) > 1e-10:
        rel_threshold[m] = threshold_2sigma[m] / abs(baseline_gen0[m]) * 100
    else:
        rel_threshold[m] = None

def compute_onset(exp_dir):
    data = load_metrics(exp_dir)
    if data is None:
        return None
    gen0 = data[0]
    onset = {}
    for m in METRICS:
        onset[m] = None
        for gen_data in data[1:]:
            if abs(gen_data[m] - gen0[m]) > threshold_2sigma[m]:
                onset[m] = gen_data["generation"]
                break
    return onset

def min_none(*vals):
    filtered = [v for v in vals if v is not None]
    return min(filtered) if filtered else None

