    "a035_s42_fp32": {"alpha": 0.35, "seed": 42, "domain": "wikitext"},
    "a040_s42_fp32": {"alpha": 0.40, "seed": 42, "domain": "wikitext"},
    "a045_s42_fp32": {"alpha": 0.45, "seed": 42, "domain": "wikitext"},
    "a045_s43_fp32": {"alpha": 0.45, "seed": 43, "domain": "wikitext"},
    "a050_s42_fp32": {"alpha": 0.50, "seed": 42, "domain": "wikitext"},
    "a050_s43_fp32": {"alpha": 0.50, "seed": 43, "domain": "wikitext"},
    "a050_s44_fp32": {"alpha": 0.50, "seed": 44, "domain": "wikitext"},
